INSERT INTO `eventdb` (`event_name`, `event_id`, `event_date`, `event_time`, `event_venue`, `max_participants`, `is_group`, `group_counts`, `group_participants`, `allowance`, `gender`, `image`, `event_type`, `event_rules`, `event_cordinators`) VALUES
('CARBON ART', 1, '08/09/2025', '09:45 AM – 10:45 AM', 'Class Room', 4, 1, 4, 1, 4, 'COMMON', 'public/images/event/CARBON ART.jpg', 'Off Stage', 'It is a solo event.	\nThis event is for both boys and girls teams.\nParticipants Rule : 4 students(maximum) can represent their team.\nTime limit: 1 hour.\nThe topic will be given on the spot.\n', 'MR.K.GANESH|DR.M.VEERAKUMAR'),
('SHORT FILM SHOWCASE', 2, '10/09/25', '09:45 AM – 10:45 AM', 'Sir.C.V.Raman Auditorium', 8, 0, 0, 0, 8, 'COMMON', 'public/images/event/CINESNAP.jpg', 'Off Stage', 'It is a team event.\r\nThis event is for both boys and girls teams.\r\nParticipants count: 8 members per team.\r\nAll film submissions must be original work created by the entrant team.\r\nFilms must not contain any copyrighted material or elements without proper authorization.\r\nFilms should be submitted to the Event Coordinators by the specified deadline.\r\nSubmit films in the specified format (MP4/AVI/MOV/MKV) with high-quality video and audio; include English subtitles if the primary language is not English.\r\nTime limit for each film: 5 minutes.\r\nTopics: Finalize on the day of lot confirmation.', 'MR.J.CHAKARAVARTHY SAMY DURAI|MR.R.UDHAYA KUMAR'),
('PICASSO ON GLASS', 3, '08/09/2025', '11:00 PM to 11:45 PM', 'Ohm’s Lab', 8, 1, 4, 2, 8, 'COMMON', 'public/images/event/PICASSOONGLASS.jpg', 'Off Stage', 'It is a team event.\r\n\r\nThis event is for both boys and girls teams.\r\n\r\nParticipants count: 4 different groups in team, 2 members in each team.\r\n\r\nTime limit: 1 hour.\r\n\r\nThe participants should bring all necessary materials.\r\n\r\nTheme: Finalize on the day of lot confirmation.', 'MR.A.VENNIMALAI RAJAN|MRS.BENITA MERLIN ISBELLA'),
('ARTY CRAFTY', 4, '08/09/2025', '12:00 PM to 01:00 PM', 'Chemistry Lab', 8, 1, 4, 2, 8, 'COMMON', 'public/images/event/ARTYCRAFTY.jpg', 'Off Stage', 'This event is for both boys and girls teams.\r\n\r\nParticipants count: 4 different groups in team, 2 members in each team.\r\n\r\nTime limit: 1 hour.\r\n\r\nThe participants should bring all necessary materials, but only waste materials should be used.\r\n\r\nBringing any structure that is partially or fully made is not allowed.\r\n\r\nGlue, pins, threads, and colours may be used to enhance finishing.\r\n\r\nJudges reserve the right to disqualify any artwork not created primarily with waste materials.\r\n', 'MR THIRUMALAIRAJ|MRS.S.MAHALAKSHMI'),
('TALK ON THE SPOT', 5, '08/09/2025', '01:00 PM to 02:00 PM', 'Sir.C.V.Raman Auditorium', 4, 1, 4, 1, 4, 'COMMON', 'public/images/event/TALKONTHESPOT.jpg', 'Off Stage', 'It is a solo event.\r\n\r\nParticipants can choose to speak in either Tamil or English but must not mix languages during their speech.\r\n\r\nThis event is open to both boys and girls.\r\n\r\nParticipants count: 4 per team.\r\n\r\nThe event allows 2 minutes for preparation and 3 minutes for the talk.\r\n\r\nThe topic will be given on the spot.\r\n\r\nJudging will be based on relevance to the title, fluency, organized content delivery, and clarity of the presentation.', 'MR.V.SIVAGANESAN |MR.R.DHANDAYUTHAPANI'),
('BLOSSOM & CRAFTS', 6, '08/09/2025', '01:00 PM to 02:00 PM', 'Physics Lab', 8, 1, 4, 2, 8, 'COMMON', 'public/images/event/BLOSSOMAND CRAFT.jpg', 'Off Stage', 'It is a team event.\r\n\r\nThis event is open to both boys and girls teams.\r\n\r\nParticipants count: 4 different groups in team, 2 members in each group.\r\n\r\nTime limit: 1 hour.\r\n\r\nParticipants should bring all necessary materials for their project.', 'MR C. SHIVA|MRS.P.NAGAJOTHI'),
('CARVO', 8, '09/09/2025', '02:00 PM to 03:00 PM', 'Chemistry Lab', 6, 1, 2, 3, 6, 'COMMON', 'public/images/event/carvo.jpg', 'Off Stage', 'It is a team event.\r\n\r\nThis event is for both boys and girls teams.\r\n\r\nParticipants count: 2 groups per team, with 3 members in each group.\r\n\r\nTime limit: 1 hour.\r\n\r\nThe participants should bring all necessary materials.', 'MR.R.SANTHASEELAN|MR.T.HARIPRASATH'),
('HANDY HENNA', 9, '09/09/2025', '09:45 AM to  10:45 AM', 'Class Room', 8, 1, 4, 2, 8, 'GIRLS', 'public/images/event/HANDYHENNA.jpg', 'Off Stage', 'This event is for girls teams only.\r\n\r\nIt is a team event.\r\n\r\nParticipants count: 4 groups per team, with 2 members in each group.\r\n\r\nTime limit: 1 hour.\r\n\r\nParticipants should bring all necessary materials.\r\n\r\nDesigns must be created by the participants themselves without using references like design books or stickers.\r\n\r\nMehndi should be applied on one hand covering both palm and dorsal sides.\r\n\r\nJudges\' decisions are final.', 'MS.B.ABINAYA|MRS.M.VENKATALAKSHMI'),
('HAIRY DORA', 10, '09/09/2025', '11:00 AM to 12:00 PM', 'Physics Lab', 4, 1, 2, 2, 4, 'GIRLS', 'public/images/event/HAIRYDORA.jpg', 'Off Stage', 'It is a team event.\r\n\r\nThis event is for girls teams only.\r\n\r\nParticipants count: 2 groups per team, with 2 members in each group.\r\n\r\nTime limit: 1 hour.\r\n\r\nThe participants should bring all necessary materials.\r\n\r\nHair designs and styling should be original and created during the competition.\r\n\r\nAll necessary styling tools and products are to be provided by participants.\r\n\r\nPre-cutting or pre-styling of hair before the event is not allowed.\r\n\r\nJudging will be based on creativity, technique, and overall presentation.', 'MRS G. KEERTHANA|MRS.M.PAVITHRA'),
('ONSTAGE ODYSSEY', 11, '09/09/2025', '12:15 PM to 01:15 PM', 'Sir C.V.Raman Auditorium', 7, 1, 1, 7, 7, 'GIRLS', 'public/images/event/ONSTAGEODYSSEY.jpg', 'Off Stage', 'It is a team event exclusively for girls teams.\r\n\r\nEach team is allowed a maximum of 7 participants.\r\n\r\nThe total performance time should not exceed 5 minutes.\r\n\r\nTeams must inform the organizers and event coordinator of their chosen theme at least two days before the event.\r\n\r\nThe theme should revolve around creating awareness about a specific issue or topic.\r\n\r\nThe complete skit should be in the English language.\r\n\r\nSafety is a priority; use of fire, water, glass, or any materials that could litter the stage is strictly prohibited.\r\n\r\nAudio tracks should be submitted and verified with the event coordinator on the day before the event.\r\n\r\nJudging criteria include creativity, team coordination, use of costumes, and properties within the performance.', 'DR.P.MALARVIZHI|MRS.T.SUBATHAMANI'),
('CUISINE MASTER', 12, '09/09/2025', '01:15 PM to 03:15 PM', 'Physics Lab & EVS Lab', 6, 1, 2, 3, 6, 'COMMON', 'public/images/event/CUISINEMASTER.jpg', 'Off Stage', 'It is a team event.\r\n\r\nThis event is for both boys and girls teams.\r\n\r\nEach team is composed of 2 groups, with 3 members in each group.\r\n\r\nOnly specified ingredients are allowed; the details will be announced by the event coordinator two days before the event.\r\n\r\nTime limit: 1 hour.\r\n\r\nParticipants are responsible for bringing all the necessary materials for their cooking project.\r\n\r\nParticipants may use an induction stove for cooking.\r\n\r\nUse of open flames or fire is strictly prohibited for safety reasons.\r\n\r\nJudging will be based on taste and creativity.', 'DR V ANANTHI|DR.R.VALARMATHI'),
('WARRIORS SHOWCASE', 13, '09/09/2025', '09:45 AM – 10:45 AM', 'Play Ground', 2, 1, 2, 1, 2, 'COMMON', 'public/images/event/WARRIORS SHOWCASE.png', 'Off Stage', 'It is a team event for both boys teams and girls teams.\r\n\r\nIt is a solo event.\r\n\r\nParticipants count: 2 participants per team (maximum).\r\n\r\nThe allotted time limit for the performance is 5 minutes.\r\n\r\nParticipants are responsible for bringing all necessary materials.\r\n\r\nPerformance can include Yoga, Karate, Silambam.\r\n\r\nThe use of fire and glass is strictly prohibited for safety reasons.', 'MR.K.SUNDARARAJAN|MRS. MALINI'),
('PICASSO ON FACE', 14, '09/09/2025', '11:00 AM to 12:00 PM', 'Class Room', 8, 1, 4, 2, 8, 'BOYS', 'public/images/event/PICASSO ON FACE.jpg', 'Off Stage', 'It is a team event, exclusive for boys.\r\n\r\nParticipants count: 4 groups per team, with 2 members in each group.\r\n\r\nTime limit: 1 hour.\r\n\r\nParticipants should bring all necessary paints, brushes, and materials.\r\n\r\nTheme will be Nature and Wildlife.\r\n\r\nPaints used must be skin-safe and non-toxic.\r\n\r\nUse of stencils is generally not allowed; designs must be free-hand.\r\n\r\nCreativity, originality, neatness, and adherence to the theme will be judged.\r\n\r\nNo use of offensive or inappropriate content.\r\n\r\nJudges’ decisions are final and binding.', 'MR.C.SURULIMANI|MR.N.KESAVAMOORTHY'),
('GAMERS GAUNTLET', 15, '09/09/2025', '12:15 PM to 01:15 PM', 'Dennis Lab', 4, 1, 2, 2, 4, 'BOYS', 'public/images/event/GAMERS GAUNTLET.jpg', 'Off Stage', 'It is a team event with 2 participants per team.\r\n\r\nTwo teams can participate per house.\r\n\r\nAll participants should be familiar with the rules and gameplay of the selected game.\r\n\r\nMatches will be played on LAN (Local Area Network) to ensure fair play.\r\n\r\nParticipants must bring their own gaming equipment, including gaming keyboards and audio accessories (if available).\r\n\r\nOrganizers provide infrastructure like network connections and power outlets.\r\n\r\nAll software and game updates will be installed and up to date before the competition begins.\r\n\r\nParticipants must exhibit good sportsmanship and fair play at all times.\r\n\r\nCheating, hacking, or using unauthorized third-party software is strictly prohibited and will result in immediate disqualification.\r\n\r\nTeams must pick their places at the venue and check their hardware before the event starts. Trial play is not allowed.\r\n\r\nWinners are chosen by wins and losses; in case of a tie, kills and deaths are considered.\r\n\r\nDamaging any hardware will result in disqualification of the team.', 'MR.R.SHANMUGAPRIYAN|MR.K.VELKUMAR'),
('SNAPOGRAPHY', 16, '09/09/2025', '02:45 PM to 03:45 PM', 'Class Room-7', 8, 1, 4, 2, 8, 'COMMON', 'public/images/event/SNAPOGRAPHY.JPG', 'Off Stage', 'It is a team event open to both boys and girls teams.\r\n\r\nEach team comprises 4 groups, with 2 members in each group.\r\n\r\nTime limit: 1 hour.\r\n\r\nParticipants are required to bring a professional camera; use of mobile phones is strictly prohibited.\r\n\r\nThe theme for the photography competition will be given on the spot.\r\n\r\nContent must be original and created within the campus premises.\r\n\r\nPhotos should be original and not previously published or awarded.\r\n\r\nBasic editing (colour enhancement, cropping) may be allowed, but digital manipulation or altering the content is prohibited.\r\n\r\nInappropriate or offensive content is strictly prohibited and will lead to disqualification.\r\n\r\nJudges will evaluate originality, concept, technical excellence, composition, and artistic merit.\r\n\r\nThe judges\' decision is final and binding.', 'Dr.N.DAVID MATHAN|Mr.R.SHANMUGAPRIYAN'),
('MUSICAL RHAPSODY', 17, '11/09/25', ' 10:00 AM to 11:00 AM', 'Kamarajar Open Auditorium', 2, 1, 2, 1, 2, 'COMMON', 'public/images/event/MUSICAL RHAPSODY.jpg', 'On Stage', 'It is a solo event.\r\nEach team can have two participants.\r\nOpen to all genders (boys and girls teams).\r\nTime limit for each performance should not exceed 5 minutes.\r\nParticipants must adhere to performance guidelines such as appropriate song choice and decorum.\r\nJudging criteria generally include vocal quality, rhythm, composition, and overall impression.\r\nUse of vulgar, sexually explicit, or violent language/lyrics is strictly prohibited.\r\nParticipants should dress appropriately.\r\nThe decision of the judges will be final.\r\n', 'MRS R. KEERTHANA|MRS.R.ARCHANA'),
('ANY BODY CAN DANCE', 18, '12/09/25', '12:45 PM to 02:45 PM', 'Kamarajar Open Auditorium', 15, 1, 1, 15, 15, 'COMMON', 'public/images/event/ANY BODY CAN DANCE.jpg', 'On Stage', 'It is a team performance open to both boys and girls teams.\r\nEach team is allowed a maximum of 15 participants,(minimum 10).\r\nPerformance duration should not exceed 10 minutes in total: 7 minutes for the team\'s chosen Indian folk dance and 3 minutes for a \"foot loose\" segment.\r\nThe dance style must be rooted in Indian folk traditions and reflect the country\'s cultural heritage.\r\nSafety is prioritized; use of fire, water, glass, or materials that could litter the stage is strictly prohibited.\r\nTeams must submit their audio track to the event coordinator before the event.\r\nJudging will be based on creativity, team coordination, presentation, costumes, and use of props.\r\nParticipants should wear appropriate traditional costumes and makeup reflecting the folk culture.\r\nThe stage should be cleaned of any props or litter immediately after the performance.\r\nThe judges\' decision is final and binding.\r\n', 'MR.M.IDHAYACHANDRAN|MRS.R.CHITRA'),
('CHOREO BOOM', 19, '13/09/25', '11.15 AM to 01.15 PM', 'Kamarajar Open Auditorium', 15, 0, 0, 0, 15, 'COMMON', 'public/images/event/CHOREO BOOM.jpg', 'On Stage', 'It is a team performance open to both boys and girls teams.\r\nEach team is allowed a maximum of 15 participants(minimum 10).\r\nTotal performance time should not exceed 10 minutes: 7 minutes for the team\'s own choice of western dance and 3 minutes for a \"foot loose\" segment, all purely western style.\r\nThe performance should be cultured and a pleasant piece of art.\r\nSafety is a priority; use of fire, water, glass, or any materials that could litter the stage is strictly prohibited.\r\nTeams must submit their chosen audio track to the event coordinator.\r\nJudging criteria include creativity, team coordination, use of costumes, and use of properties in the performance.\r\n', 'MRS.P. SHANTHADEVI|MS.S.ABIRAMI KAYATHIRI'),
('NSCET TRENDSETTERS', 20, '11/09/25', '2.00 PM to 03:00 PM', 'Kamarajar Open Auditorium', 1, 1, 1, 1, 1, 'COMMON', 'public/images/event/NSCET TRENDSETTERS.jpg', 'On Stage', 'It is a solo event with only one participant per team, Common for boys and Girls.\r\nEach participant will have a maximum of 3 minutes for their performance, including time for setup and ramp walk.\r\nAfter ramp Walk 3 to 5 general knowledge question will be asked to the participants.\r\nParticipants must design and wear their own costumes or carry original designs adhering to the theme.\r\nProps may be used but must be pre-approved by the organizers and should not include hazardous materials like fire, smoke, or water.\r\nAudio tracks for the performance must be submitted in advance in mp3 format via pen drive or other means specified by the organizers.\r\nVulgarity, obscenity, or indecent costumes/behaviour will lead to disqualification.\r\nParticipants are judged on costume creativity, theme adherence, stage presence, confidence, and overall impact.\r\nParticipants must ensure their area remains clean and free of debris after their performance,The judge’s decision will be final and binding.', 'MRS.S.RAJYASHREE|MRS.M.BHAVANI'),
('MIME ODYSSEY', 21, '11/09/25', '3.15 PM to 4.30 PM', 'Kamarajar Open Auditorium', 12, 1, 1, 12, 12, 'COMMON', 'public/images/event/MIME ODYSSEY.jpg', 'On Stage', 'Each team can have a maximum of 12 members(minimum 10).\r\nThe mime act must not contain any dialogues or lip-syncing.\r\nNo offensive, obscene, or disrespectful actions or gestures are allowed,violation will lead to immediate disqualification.\r\nUse of makeup, drapery, and background music is allowed to enhance the presentation.\r\nThe time limit for each team is usually 10 minutes and must not be exceeded.\r\nJudging criteria focus on creativity, idea quality, acting, use of makeup and music, and overall impression.\r\nThe decision of the judges is final and binding.\r\nVulgar or bitter insinuations should be avoided; the performance should be pleasant, satirical, or humorous if applicable\r\n', 'MRS.K.DEEPIGA |MRS.H.JURIYA BANU'),
('NEEYA NANAA', 22, '10/09/25', '12:15 PM to 01:15 PM', 'Sir.C.V.Raman Auditorium', 1, 0, 0, 0, 1, 'COMMON', 'public/images/event/NEEYA NAANA.png', 'Off Stage', 'It is a one-on-one debate.\n\nFrom each team, one student can participate.\n\nThe topics will be provided on the spot.\n\nThe judge\'s decision is final and binding.\n\nTime limits per round and rebuttal will be given by the organizers on event day.\n\nNo use of electronic devices or reference materials during debate.', 'MRS.N.THISHA|MRS.P.JASMINE ROSE'),
('KAVITHIDAL', 23, '10/09/25', '11:00 AM to 12:00 PM', 'Conference Hall', 2, 0, 0, 0, 2, 'COMMON', 'public/images/event/KAVITHIRAL.png', 'Off Stage', 'It is a single-round competition. It is a solo event.\r\n\r\nIt is open to both boys and girls teams.\r\n\r\nParticipants rule: 2 students (maximum) can represent their team.\r\n\r\nThe topic will be given by the event coordinator one day before the event.\r\n\r\nParticipants are expected to recite based on the given topic.\r\n\r\nThe competition will be judged based on pronunciation, intonation, stress, voice, and tone.\r\n\r\nParticipants are not allowed to refer to any external materials during the competition.\r\n\r\nThe judge\'s decision is final and binding.\r\n\r\nTopics: Finalize on the day of lot confirmation.', 'MRS.P.NIRANJANA|MR.V.SIVAGANESAN'),
('RANGOLI', 24, '10/09/25', '09:45 AM – 10:45 AM', 'Front Portico', 4, 1, 2, 2, 4, 'GIRLS', 'public/images/event/RANGOLI.jpg', 'Off Stage', 'It is a team event, exclusive for girls.\r\n\r\nParticipants count: 2 groups per team, with 2 members in each group.\r\n\r\nTime duration: 1 hour.\r\n\r\nParticipants need to bring their own materials.\r\n\r\nOnly colour powder should be used for creating the rangoli.\r\n\r\nParticipants are typically not allowed to refer to printed materials during the competition.\r\n\r\nJudging criteria generally include creativity, clarity, colour combination, neatness, and adherence to theme (when available).\r\n\r\nThe judges’ decision will be final and binding.\r\n\r\nTheme will be finalized on the day of lot taking process.', 'MRS.J.PREETHA|MRS R. KARUNIYAH'),
('TRANSLATION', 25, '10/09/25', '01.15 PM to 02.15 PM', 'Sir.C.V.Raman Auditorium', 4, 1, 2, 2, 4, 'COMMON', 'public/images/event/TRANSLATION.png', 'Off Stage', 'It is open to both boys and girls teams.\r\n\r\nParticipants count: 2 groups per team, with 2 members in each group.\r\n\r\nThe competition will have a total of 2 rounds. First round will be Proverbs Translation. Second round will be translating a short story from one language to another, focusing on both accuracy and creativity.\r\n\r\nContent for translation will be given on the spot during the event.\r\n\r\nThe decision will be based on timing and spelling mistakes.\r\n\r\nTeams are expected to translate accurately and quickly within the time limits.\r\n\r\nNo use of electronic devices or external help during translation.\r\n\r\nThe judges\' decision will be final and binding.', 'MRS.M.ARULVIZHI|MRS. S. JOTHI'),
('INSTAREEL RIVALS', 26, '10/09/25', '10.30 AM – 11.30 AM', 'Sir.C.V.Raman Auditorium', 4, 1, 2, 4, 4, 'COMMON', 'public/images/event/w.png', 'Off Stage', 'It is open to both boys and girls teams.\r\nParticipants count: 2 groups per team, with 2 members in each group.\r\nEach team must create 1 Instagram-style reel (video).\r\nTime limit: Minimum 30 minutes – Maximum 45 minutes.\r\nContent must be original and created within the campus premises.\r\nUse of stock footage or downloaded clips is not allowed.\r\nTeams may use music, filters, and effects available in editing apps, but plagiarism of other reels is strictly prohibited.\r\n', 'MR.R.UDHAYA KUMAR|MRS.G.KEERTHIGA'),
('MINIATURE CARVING', 27, '10/09/25', ' 02:30 PM to 03:30 PM', 'Chemistry Lab', 4, 1, 1, 4, 4, 'COMMON', 'public/images/event/miniature-pencil-tip-sculptures-daya-micro-art.png', 'Off Stage', 'Time Limit: Each team will be given 90 minutes to complete their carving.\r\nEach team consists of 4 members.\r\n It is a team event for both boys teams and girls teams.\r\nAllowed materials for carving:\r\nSoap, chalk, wax, thermocol, or soft wood (as provided/approved by organizers).\r\nTools must be brought by participants (small knives, carving tools, toothpicks, etc.).\r\nCarvings must be miniature-sized (within a maximum of 10 cm × 10 cm × 10 cm).\r\nDesigns should be original and created during the competition only (no pre-made work allowed).\r\nTeams must maintain cleanliness at their workspace and handle tools safely.\r\nUse of power tools, blades larger than 6 inches, or unsafe equipment is strictly prohibited.\r\nParticipants must not copy existing miniature designs from the internet or other sources.\r\nObscene, offensive, or inappropriate carvings will lead to disqualification.\r\n', 'DR.N.PANDI SELVI|MRS.J.KANIMOLI'),
('As You Like It(Standup Comedy/Musical Instruments Play)', 28, '12/09/25', '03:45 PM to 04:45 PM', 'Kamarajar Open Auditorium', 4, 1, 1, 4, 4, 'COMMON', 'public/images/event/2.png', 'On Stage', 'Teams may choose either:\r\nStand-Up Comedy: Original content, jokes, anecdotes.\r\nOr\r\nMusical Instrument Performance: Solo/ensemble instrumental piece.\r\n\r\nIt is a team event for both boys teams and girls teams.\r\nEach team consists of 4 members(maximum).\r\nPerformances must be original and self-prepared (no direct copying).\r\nMusical performances should not include full karaoke-style singing – the focus is on instruments.\r\nComedy performances may be in English, Tamil, or bilingual.\r\nProps/instruments should be arranged by the participants themselves.\r\n', 'MS.S.MEGHA|MRS.B.SAI SUGANYA');
INSERT INTO `event_slots` (`event_id`, `event_name`, `event_date`, `event_time`, `event_venue`, `max_participants`, `is_group`, `group_counts`, `group_participants`, `allowance`, `gender`, `image`, `event_type`, `event_rules`, `event_cordinators`) VALUES
(1, 'HANDY HENNA', '09/09/2025', '09:45 AM to  10:45 AM', 'Class Room', 8, 1, 4, 2, 8, 'GIRLS', 'public/images/event/HANDYHENNA.jpg', 'Off Stage', 'This event is for girls teams only.\r\n\r\nIt is a team event.\r\n\r\nParticipants count: 4 groups per team, with 2 members in each group.\r\n\r\nTime limit: 1 hour.\r\n\r\nParticipants should bring all necessary materials.\r\n\r\nDesigns must be created by the participants themselves without using references like design books or stickers.\r\n\r\nMehndi should be applied on one hand covering both palm and dorsal sides.\r\n\r\nJudges\' decisions are final.', 'MS.B.ABINAYA|MRS.M.VENKATALAKSHMI'),
(2, 'HAIRY DORA', '09/09/2025', '11:00 AM to 12:00 PM', 'Physics Lab', 4, 1, 2, 2, 4, 'GIRLS', 'public/images/event/HAIRYDORA.jpg', 'Off Stage', 'It is a team event.\r\n\r\nThis event is for girls teams only.\r\n\r\nParticipants count: 2 groups per team, with 2 members in each group.\r\n\r\nTime limit: 1 hour.\r\n\r\nThe participants should bring all necessary materials.\r\n\r\nHair designs and styling should be original and created during the competition.\r\n\r\nAll necessary styling tools and products are to be provided by participants.\r\n\r\nPre-cutting or pre-styling of hair before the event is not allowed.\r\n\r\nJudging will be based on creativity, technique, and overall presentation.', 'MRS G. KEERTHANA|MRS.M.PAVITHRA'),
(3, 'ONSTAGE ODYSSEY', '09/09/2025', '12:15 PM to 01:15 PM', 'Sir C.V.Raman Auditorium', 7, 1, 1, 7, 7, 'GIRLS', 'public/images/event/ONSTAGEODYSSEY.jpg', 'Off Stage', 'It is a team event exclusively for girls teams.\r\n\r\nEach team is allowed a maximum of 7 participants.\r\n\r\nThe total performance time should not exceed 5 minutes.\r\n\r\nTeams must inform the organizers and event coordinator of their chosen theme at least two days before the event.\r\n\r\nThe theme should revolve around creating awareness about a specific issue or topic.\r\n\r\nThe complete skit should be in the English language.\r\n\r\nSafety is a priority; use of fire, water, glass, or any materials that could litter the stage is strictly prohibited.\r\n\r\nAudio tracks should be submitted and verified with the event coordinator on the day before the event.\r\n\r\nJudging criteria include creativity, team coordination, use of costumes, and properties within the performance.', 'DR.P.MALARVIZHI|MRS.T.SUBATHAMANI'),
(4, 'PICASSO ON FACE', '09/09/2025', '11:00 AM to 12:00 PM', 'Class Room', 8, 1, 4, 2, 8, 'BOYS', 'public/images/event/PICASSO ON FACE.jpg', 'Off Stage', 'It is a team event, exclusive for boys.\r\n\r\nParticipants count: 4 groups per team, with 2 members in each group.\r\n\r\nTime limit: 1 hour.\r\n\r\nParticipants should bring all necessary paints, brushes, and materials.\r\n\r\nTheme will be Nature and Wildlife.\r\n\r\nPaints used must be skin-safe and non-toxic.\r\n\r\nUse of stencils is generally not allowed; designs must be free-hand.\r\n\r\nCreativity, originality, neatness, and adherence to the theme will be judged.\r\n\r\nNo use of offensive or inappropriate content.\r\n\r\nJudges’ decisions are final and binding.', 'MR.C.SURULIMANI|MR.N.KESAVAMOORTHY'),
(5, 'GAMERS GAUNTLET', '09/09/2025', '12:15 PM to 01:15 PM', 'Dennis Lab', 4, 1, 2, 2, 4, 'BOYS', 'public/images/event/GAMERS GAUNTLET.jpg', 'Off Stage', 'It is a team event with 2 participants per team.\r\n\r\nTwo teams can participate per house.\r\n\r\nAll participants should be familiar with the rules and gameplay of the selected game.\r\n\r\nMatches will be played on LAN (Local Area Network) to ensure fair play.\r\n\r\nParticipants must bring their own gaming equipment, including gaming keyboards and audio accessories (if available).\r\n\r\nOrganizers provide infrastructure like network connections and power outlets.\r\n\r\nAll software and game updates will be installed and up to date before the competition begins.\r\n\r\nParticipants must exhibit good sportsmanship and fair play at all times.\r\n\r\nCheating, hacking, or using unauthorized third-party software is strictly prohibited and will result in immediate disqualification.\r\n\r\nTeams must pick their places at the venue and check their hardware before the event starts. Trial play is not allowed.\r\n\r\nWinners are chosen by wins and losses; in case of a tie, kills and deaths are considered.\r\n\r\nDamaging any hardware will result in disqualification of the team.', 'MR.R.SHANMUGAPRIYAN|MR.K.VELKUMAR'),
(6, 'RANGOLI', '10/09/25', '09:45 AM – 10:45 AM', 'Front Portico', 4, 1, 2, 2, 4, 'GIRLS', 'public/images/event/RANGOLI.jpg', 'Off Stage', 'It is a team event, exclusive for girls.\r\n\r\nParticipants count: 2 groups per team, with 2 members in each group.\r\n\r\nTime duration: 1 hour.\r\n\r\nParticipants need to bring their own materials.\r\n\r\nOnly colour powder should be used for creating the rangoli.\r\n\r\nParticipants are typically not allowed to refer to printed materials during the competition.\r\n\r\nJudging criteria generally include creativity, clarity, colour combination, neatness, and adherence to theme (when available).\r\n\r\nThe judges’ decision will be final and binding.\r\n\r\nTheme will be finalized on the day of lot taking process.', 'MRS.J.PREETHA|MRS R. KARUNIYAH'),
(8, 'CARBON ART', '08/09/2025', '09:45 AM – 10:45 AM', 'Class Room', 4, 1, 4, 1, 4, 'BOYS', 'public/images/event/CARBON ART.jpg', 'Off Stage', 'It is a solo event.	\nThis event is for both boys and girls teams.\nParticipants Rule : 4 students(maximum) can represent their team.\nTime limit: 1 hour.\nThe topic will be given on the spot.\n', 'MR.K.GANESH|DR.M.VEERAKUMAR'),
(9, 'SHORT FILM SHOWCASE', '10/09/25', '09:45 AM – 10:45 AM', 'Sir.C.V.Raman Auditorium', 8, 1, 8, 8, 8, 'BOYS', 'public/images/event/CINESNAP.jpg', 'Off Stage', 'It is a team event.\r\nThis event is for both boys and girls teams.\r\nParticipants count: 8 members per team.\r\nAll film submissions must be original work created by the entrant team.\r\nFilms must not contain any copyrighted material or elements without proper authorization.\r\nFilms should be submitted to the Event Coordinators by the specified deadline.\r\nSubmit films in the specified format (MP4/AVI/MOV/MKV) with high-quality video and audio; include English subtitles if the primary language is not English.\r\nTime limit for each film: 5 minutes.\r\nTopics: Finalize on the day of lot confirmation.', 'MR.J.CHAKARAVARTHY SAMY DURAI|MR.R.UDHAYA KUMAR'),
(10, 'PICASSO ON GLASS', '08/09/2025', '11:00 PM to 11:45 PM', 'Ohm’s Lab', 8, 1, 4, 2, 8, 'BOYS', 'public/images/event/PICASSOONGLASS.jpg', 'Off Stage', 'It is a team event.\r\n\r\nThis event is for both boys and girls teams.\r\n\r\nParticipants count: 4 different groups in team, 2 members in each team.\r\n\r\nTime limit: 1 hour.\r\n\r\nThe participants should bring all necessary materials.\r\n\r\nTheme: Finalize on the day of lot confirmation.', 'MR.A.VENNIMALAI RAJAN|MRS.BENITA MERLIN ISBELLA'),
(11, 'ARTY CRAFTY', '08/09/2025', '12:00 PM to 01:00 PM', 'Chemistry Lab', 8, 1, 4, 2, 8, 'BOYS', 'public/images/event/ARTYCRAFTY.jpg', 'Off Stage', 'This event is for both boys and girls teams.\r\n\r\nParticipants count: 4 different groups in team, 2 members in each team.\r\n\r\nTime limit: 1 hour.\r\n\r\nThe participants should bring all necessary materials, but only waste materials should be used.\r\n\r\nBringing any structure that is partially or fully made is not allowed.\r\n\r\nGlue, pins, threads, and colours may be used to enhance finishing.\r\n\r\nJudges reserve the right to disqualify any artwork not created primarily with waste materials.\r\n', 'MR THIRUMALAIRAJ|MRS.S.MAHALAKSHMI'),
(12, 'TALK ON THE SPOT', '08/09/2025', '01:00 PM to 02:00 PM', 'Sir.C.V.Raman Auditorium', 4, 1, 4, 1, 4, 'BOYS', 'public/images/event/TALKONTHESPOT.jpg', 'Off Stage', 'It is a solo event.\r\n\r\nParticipants can choose to speak in either Tamil or English but must not mix languages during their speech.\r\n\r\nThis event is open to both boys and girls.\r\n\r\nParticipants count: 4 per team.\r\n\r\nThe event allows 2 minutes for preparation and 3 minutes for the talk.\r\n\r\nThe topic will be given on the spot.\r\n\r\nJudging will be based on relevance to the title, fluency, organized content delivery, and clarity of the presentation.', 'MR.V.SIVAGANESAN |MR.R.DHANDAYUTHAPANI'),
(13, 'BLOSSOM & CRAFTS', '08/09/2025', '01:00 PM to 02:00 PM', 'Physics Lab', 8, 1, 4, 2, 8, 'BOYS', 'public/images/event/BLOSSOMAND CRAFT.jpg', 'Off Stage', 'It is a team event.\r\n\r\nThis event is open to both boys and girls teams.\r\n\r\nParticipants count: 4 different groups in team, 2 members in each group.\r\n\r\nTime limit: 1 hour.\r\n\r\nParticipants should bring all necessary materials for their project.', 'MR C. SHIVA|MRS.P.NAGAJOTHI'),
(14, 'CARVO', '09/09/2025', '02:00 PM to 03:00 PM', 'Chemistry Lab', 6, 1, 2, 3, 6, 'BOYS', 'public/images/event/carvo.jpg', 'Off Stage', 'It is a team event.\r\n\r\nThis event is for both boys and girls teams.\r\n\r\nParticipants count: 2 groups per team, with 3 members in each group.\r\n\r\nTime limit: 1 hour.\r\n\r\nThe participants should bring all necessary materials.', 'MR.R.SANTHASEELAN|MR.T.HARIPRASATH'),
(15, 'CUISINE MASTER', '09/09/2025', '01:15 PM to 03:15 PM', 'Physics Lab & EVS Lab', 6, 1, 2, 3, 6, 'BOYS', 'public/images/event/CUISINEMASTER.jpg', 'Off Stage', 'It is a team event.\r\n\r\nThis event is for both boys and girls teams.\r\n\r\nEach team is composed of 2 groups, with 3 members in each group.\r\n\r\nOnly specified ingredients are allowed; the details will be announced by the event coordinator two days before the event.\r\n\r\nTime limit: 1 hour.\r\n\r\nParticipants are responsible for bringing all the necessary materials for their cooking project.\r\n\r\nParticipants may use an induction stove for cooking.\r\n\r\nUse of open flames or fire is strictly prohibited for safety reasons.\r\n\r\nJudging will be based on taste and creativity.', 'DR V ANANTHI|DR.R.VALARMATHI'),
(16, 'WARRIORS SHOWCASE', '09/09/2025', '09:45 AM – 10:45 AM', 'Play Ground', 2, 1, 2, 1, 2, 'BOYS', 'public/images/event/WARRIORS SHOWCASE.png', 'Off Stage', 'It is a team event for both boys teams and girls teams.\r\n\r\nIt is a solo event.\r\n\r\nParticipants count: 2 participants per team (maximum).\r\n\r\nThe allotted time limit for the performance is 5 minutes.\r\n\r\nParticipants are responsible for bringing all necessary materials.\r\n\r\nPerformance can include Yoga, Karate, Silambam.\r\n\r\nThe use of fire and glass is strictly prohibited for safety reasons.', 'MR.K.SUNDARARAJAN|MRS. MALINI'),
(17, 'SNAPOGRAPHY', '09/09/2025', '02:45 PM to 03:45 PM', 'Class Room-7', 8, 1, 4, 2, 8, 'BOYS', 'public/images/event/SNAPOGRAPHY.JPG', 'Off Stage', 'It is a team event open to both boys and girls teams.\r\n\r\nEach team comprises 4 groups, with 2 members in each group.\r\n\r\nTime limit: 1 hour.\r\n\r\nParticipants are required to bring a professional camera; use of mobile phones is strictly prohibited.\r\n\r\nThe theme for the photography competition will be given on the spot.\r\n\r\nContent must be original and created within the campus premises.\r\n\r\nPhotos should be original and not previously published or awarded.\r\n\r\nBasic editing (colour enhancement, cropping) may be allowed, but digital manipulation or altering the content is prohibited.\r\n\r\nInappropriate or offensive content is strictly prohibited and will lead to disqualification.\r\n\r\nJudges will evaluate originality, concept, technical excellence, composition, and artistic merit.\r\n\r\nThe judges\' decision is final and binding.', 'Dr.N.DAVID MATHAN|Mr.R.SHANMUGAPRIYAN'),
(18, 'MUSICAL RHAPSODY', '11/09/25', ' 10:00 AM to 11:00 AM', 'Kamarajar Open Auditorium', 2, 1, 2, 1, 2, 'BOYS', 'public/images/event/MUSICAL RHAPSODY.jpg', 'On Stage', 'It is a solo event.\r\nEach team can have two participants.\r\nOpen to all genders (boys and girls teams).\r\nTime limit for each performance should not exceed 5 minutes.\r\nParticipants must adhere to performance guidelines such as appropriate song choice and decorum.\r\nJudging criteria generally include vocal quality, rhythm, composition, and overall impression.\r\nUse of vulgar, sexually explicit, or violent language/lyrics is strictly prohibited.\r\nParticipants should dress appropriately.\r\nThe decision of the judges will be final.\r\n', 'MRS R. KEERTHANA|MRS.R.ARCHANA'),
(19, 'ANY BODY CAN DANCE', '12/09/25', '12:45 PM to 02:45 PM', 'Kamarajar Open Auditorium', 15, 1, 1, 15, 15, 'BOYS', 'public/images/event/ANY BODY CAN DANCE.jpg', 'On Stage', 'It is a team performance open to both boys and girls teams.\r\nEach team is allowed a maximum of 15 participants,(minimum 10).\r\nPerformance duration should not exceed 10 minutes in total: 7 minutes for the team\'s chosen Indian folk dance and 3 minutes for a \"foot loose\" segment.\r\nThe dance style must be rooted in Indian folk traditions and reflect the country\'s cultural heritage.\r\nSafety is prioritized; use of fire, water, glass, or materials that could litter the stage is strictly prohibited.\r\nTeams must submit their audio track to the event coordinator before the event.\r\nJudging will be based on creativity, team coordination, presentation, costumes, and use of props.\r\nParticipants should wear appropriate traditional costumes and makeup reflecting the folk culture.\r\nThe stage should be cleaned of any props or litter immediately after the performance.\r\nThe judges\' decision is final and binding.\r\n', 'MR.M.IDHAYACHANDRAN|MRS.R.CHITRA'),
(20, 'CHOREO BOOM', '13/09/25', '11.15 AM to 01.15 PM', 'Kamarajar Open Auditorium', 15, 1, 1, 15, 15, 'BOYS', 'public/images/event/CHOREO BOOM.jpg', 'On Stage', 'It is a team performance open to both boys and girls teams.\r\nEach team is allowed a maximum of 15 participants(minimum 10).\r\nTotal performance time should not exceed 10 minutes: 7 minutes for the team\'s own choice of western dance and 3 minutes for a \"foot loose\" segment, all purely western style.\r\nThe performance should be cultured and a pleasant piece of art.\r\nSafety is a priority; use of fire, water, glass, or any materials that could litter the stage is strictly prohibited.\r\nTeams must submit their chosen audio track to the event coordinator.\r\nJudging criteria include creativity, team coordination, use of costumes, and use of properties in the performance.\r\n', 'MRS.P. SHANTHADEVI|MS.S.ABIRAMI KAYATHIRI'),
(21, 'NSCET TRENDSETTERS', '13/09/25', '2.00 PM to 03:00 PM', 'Kamarajar Open Auditorium', 1, 1, 1, 1, 1, 'BOYS', 'public/images/event/NSCET TRENDSETTERS.jpg', 'On Stage', 'It is a solo event with only one participant per team, Common for boys and Girls.\r\nEach participant will have a maximum of 3 minutes for their performance, including time for setup and ramp walk.\r\nAfter ramp Walk 3 to 5 general knowledge question will be asked to the participants.\r\nParticipants must design and wear their own costumes or carry original designs adhering to the theme.\r\nProps may be used but must be pre-approved by the organizers and should not include hazardous materials like fire, smoke, or water.\r\nAudio tracks for the performance must be submitted in advance in mp3 format via pen drive or other means specified by the organizers.\r\nVulgarity, obscenity, or indecent costumes/behaviour will lead to disqualification.\r\nParticipants are judged on costume creativity, theme adherence, stage presence, confidence, and overall impact.\r\nParticipants must ensure their area remains clean and free of debris after their performance,The judge’s decision will be final and binding.', 'MRS.S.RAJYASHREE|MRS.M.BHAVANI'),
(22, 'MIME ODYSSEY', '10/09/25', '3.15 PM to 4.30 PM', 'Kamarajar Open Auditorium', 12, 1, 1, 12, 12, 'BOYS', 'public/images/event/MIME ODYSSEY.jpg', 'On Stage', 'Each team can have a maximum of 12 members(minimum 10).\r\nThe mime act must not contain any dialogues or lip-syncing.\r\nNo offensive, obscene, or disrespectful actions or gestures are allowed,violation will lead to immediate disqualification.\r\nUse of makeup, drapery, and background music is allowed to enhance the presentation.\r\nThe time limit for each team is usually 10 minutes and must not be exceeded.\r\nJudging criteria focus on creativity, idea quality, acting, use of makeup and music, and overall impression.\r\nThe decision of the judges is final and binding.\r\nVulgar or bitter insinuations should be avoided; the performance should be pleasant, satirical, or humorous if applicable\r\n', 'MRS.K.DEEPIGA |MRS.H.JURIYA BANU'),
(23, 'NEEYA NANAA', '10/09/25', '12:15 PM to 01:15 PM', 'Sir.C.V.Raman Auditorium', 1, 1, 1, 1, 1, 'BOYS', 'public/images/event/NEEYA NAANA.png', 'Off Stage', '1.	It is a one-on-one debate.\r\n2.	From each team, one student can participate.\r\n3.	The topics will be provided on the spot.\r\n4.	The judge\'s decision is final and binding.\r\n5.	Time limits per round and rebuttal will be given by the organizers on event day.\r\n6.	No use of electronic devices or reference materials during debate.\r\n', 'MRS.N.THISHA|MRS.P.JASMINE ROSE'),
(24, 'KAVITHIDAL', '10/09/25', '11:00 AM to 12:00 PM', 'Conference Hall', 2, 1, 2, 1, 2, 'BOYS', 'public/images/event/KAVITHIRAL.png', 'Off Stage', 'It is a single-round competition. It is a solo event.\r\n\r\nIt is open to both boys and girls teams.\r\n\r\nParticipants rule: 2 students (maximum) can represent their team.\r\n\r\nThe topic will be given by the event coordinator one day before the event.\r\n\r\nParticipants are expected to recite based on the given topic.\r\n\r\nThe competition will be judged based on pronunciation, intonation, stress, voice, and tone.\r\n\r\nParticipants are not allowed to refer to any external materials during the competition.\r\n\r\nThe judge\'s decision is final and binding.\r\n\r\nTopics: Finalize on the day of lot confirmation.', 'MRS.P.NIRANJANA|MR.V.SIVAGANESAN'),
(25, 'TRANSLATION', '10/09/25', '01.15 PM to 02.15 PM', 'Sir.C.V.Raman Auditorium', 4, 1, 2, 2, 4, 'BOYS', 'public/images/event/TRANSLATION.png', 'Off Stage', 'It is open to both boys and girls teams.\r\n\r\nParticipants count: 2 groups per team, with 2 members in each group.\r\n\r\nThe competition will have a total of 2 rounds. First round will be Proverbs Translation. Second round will be translating a short story from one language to another, focusing on both accuracy and creativity.\r\n\r\nContent for translation will be given on the spot during the event.\r\n\r\nThe decision will be based on timing and spelling mistakes.\r\n\r\nTeams are expected to translate accurately and quickly within the time limits.\r\n\r\nNo use of electronic devices or external help during translation.\r\n\r\nThe judges\' decision will be final and binding.', 'MRS.M.ARULVIZHI|MRS. S. JOTHI'),
(26, 'INSTAREEL RIVALS', '10/09/25', '10.30 AM – 11.30 AM', 'Sir.C.V.Raman Auditorium', 4, 1, 2, 2, 4, 'BOYS', 'public/images/event/w.png', 'Off Stage', 'It is open to both boys and girls teams.\r\nParticipants count: 2 groups per team, with 2 members in each group.\r\nEach team must create 1 Instagram-style reel (video).\r\nTime limit: Minimum 30 minutes – Maximum 45 minutes.\r\nContent must be original and created within the campus premises.\r\nUse of stock footage or downloaded clips is not allowed.\r\nTeams may use music, filters, and effects available in editing apps, but plagiarism of other reels is strictly prohibited.\r\n', '-'),
(27, 'MINIATURE CARVING', '10/09/25', ' 02:30 PM to 03:30 PM', 'Chemistry Lab', 4, 1, 1, 4, 4, 'BOYS', 'public/images/event/miniature-pencil-tip-sculptures-daya-micro-art.png', 'Off Stage', 'Time Limit: Each team will be given 90 minutes to complete their carving.\r\nEach team consists of 4 members.\r\n It is a team event for both boys teams and girls teams.\r\nAllowed materials for carving:\r\nSoap, chalk, wax, thermocol, or soft wood (as provided/approved by organizers).\r\nTools must be brought by participants (small knives, carving tools, toothpicks, etc.).\r\nCarvings must be miniature-sized (within a maximum of 10 cm × 10 cm × 10 cm).\r\nDesigns should be original and created during the competition only (no pre-made work allowed).\r\nTeams must maintain cleanliness at their workspace and handle tools safely.\r\nUse of power tools, blades larger than 6 inches, or unsafe equipment is strictly prohibited.\r\nParticipants must not copy existing miniature designs from the internet or other sources.\r\nObscene, offensive, or inappropriate carvings will lead to disqualification.\r\n', '-'),
(28, 'As You Like It(Standup Comedy/Musical Instruments Play)', '12/09/25', '03:45 PM to 04:45 PM', 'Kamarajar Open Auditorium', 4, 1, 1, 4, 4, 'BOYS', 'public/images/event/2.png', 'On Stage', 'Teams may choose either:\r\nStand-Up Comedy: Original content, jokes, anecdotes.\r\nOr\r\nMusical Instrument Performance: Solo/ensemble instrumental piece.\r\n\r\nIt is a team event for both boys teams and girls teams.\r\nEach team consists of 4 members(maximum).\r\nPerformances must be original and self-prepared (no direct copying).\r\nMusical performances should not include full karaoke-style singing – the focus is on instruments.\r\nComedy performances may be in English, Tamil, or bilingual.\r\nProps/instruments should be arranged by the participants themselves.\r\n', '-'),
(39, 'CARBON ART', '08/09/2025', '09:45 AM – 10:45 AM', 'Class Room', 4, 1, 4, 1, 4, 'GIRLS', 'public/images/event/CARBON ART.jpg', 'Off Stage', 'It is a solo event.	\nThis event is for both boys and girls teams.\nParticipants Rule : 4 students(maximum) can represent their team.\nTime limit: 1 hour.\nThe topic will be given on the spot.\n', 'MR.K.GANESH|DR.M.VEERAKUMAR'),
(40, 'SHORT FILM SHOWCASE', '10/09/25', '09:45 AM – 10:45 AM', 'Sir.C.V.Raman Auditorium', 8, 1, 8, 8, 8, 'GIRLS', 'public/images/event/CINESNAP.jpg', 'Off Stage', 'It is a team event.\r\nThis event is for both boys and girls teams.\r\nParticipants count: 8 members per team.\r\nAll film submissions must be original work created by the entrant team.\r\nFilms must not contain any copyrighted material or elements without proper authorization.\r\nFilms should be submitted to the Event Coordinators by the specified deadline.\r\nSubmit films in the specified format (MP4/AVI/MOV/MKV) with high-quality video and audio; include English subtitles if the primary language is not English.\r\nTime limit for each film: 5 minutes.\r\nTopics: Finalize on the day of lot confirmation.', 'MR.J.CHAKARAVARTHY SAMY DURAI|MR.R.UDHAYA KUMAR'),
(41, 'PICASSO ON GLASS', '08/09/2025', '11:00 PM to 11:45 PM', 'Ohm’s Lab', 8, 1, 4, 2, 8, 'GIRLS', 'public/images/event/PICASSOONGLASS.jpg', 'Off Stage', 'It is a team event.\r\n\r\nThis event is for both boys and girls teams.\r\n\r\nParticipants count: 4 different groups in team, 2 members in each team.\r\n\r\nTime limit: 1 hour.\r\n\r\nThe participants should bring all necessary materials.\r\n\r\nTheme: Finalize on the day of lot confirmation.', 'MR.A.VENNIMALAI RAJAN|MRS.BENITA MERLIN ISBELLA'),
(42, 'ARTY CRAFTY', '08/09/2025', '12:00 PM to 01:00 PM', 'Chemistry Lab', 8, 1, 4, 2, 8, 'GIRLS', 'public/images/event/ARTYCRAFTY.jpg', 'Off Stage', 'This event is for both boys and girls teams.\r\n\r\nParticipants count: 4 different groups in team, 2 members in each team.\r\n\r\nTime limit: 1 hour.\r\n\r\nThe participants should bring all necessary materials, but only waste materials should be used.\r\n\r\nBringing any structure that is partially or fully made is not allowed.\r\n\r\nGlue, pins, threads, and colours may be used to enhance finishing.\r\n\r\nJudges reserve the right to disqualify any artwork not created primarily with waste materials.\r\n', 'MR THIRUMALAIRAJ|MRS.S.MAHALAKSHMI'),
(43, 'TALK ON THE SPOT', '08/09/2025', '01:00 PM to 02:00 PM', 'Sir.C.V.Raman Auditorium', 4, 1, 4, 1, 4, 'GIRLS', 'public/images/event/TALKONTHESPOT.jpg', 'Off Stage', 'It is a solo event.\r\n\r\nParticipants can choose to speak in either Tamil or English but must not mix languages during their speech.\r\n\r\nThis event is open to both boys and girls.\r\n\r\nParticipants count: 4 per team.\r\n\r\nThe event allows 2 minutes for preparation and 3 minutes for the talk.\r\n\r\nThe topic will be given on the spot.\r\n\r\nJudging will be based on relevance to the title, fluency, organized content delivery, and clarity of the presentation.', 'MR.V.SIVAGANESAN |MR.R.DHANDAYUTHAPANI'),
